import os
import shutil
import csv

def task_func(target_value='332', csv_dir='./csv_files/', processed_dir='./processed_files/', simulate=False):
    result = {}

    # Ensure deterministic processing order
    if not os.path.isdir(csv_dir):
        raise FileNotFoundError(f"CSV directory not found: {csv_dir}")

    csv_files = sorted(
        f for f in os.listdir(csv_dir)
        if f.lower().endswith('.csv') and os.path.isfile(os.path.join(csv_dir, f))
    )

    for filename in csv_files:
        file_path = os.path.join(csv_dir, filename)
        found_index = None

        with open(file_path, newline='', encoding='utf-8') as csvfile:
            reader = csv.reader(csvfile)
            for idx, row in enumerate(reader):
                if row and row[0] == str(target_value):
                    found_index = idx
                    break

        if found_index is not None:
            result[filename] = found_index

        if not simulate:
            os.makedirs(processed_dir, exist_ok=True)
            shutil.move(file_path, os.path.join(processed_dir, filename))

    return result
